	public static boolean exists(str _fieldName)
    {
        return TFMfieldFromNameCreator::find(_fieldName) != null;
    }

public static TFMfieldFromNameCreator find(str _fieldName)
{
    SysDictClass sdc = new SysDictClass(classNum(TFMfieldFromNameCreator));
    ListEnumerator lEnum = sdc.extendedBy(true).getEnumerator();
    TFMfieldFromNameCreator fieldHandler;
    while (lEnum.moveNext())
    {
        fieldHandler = new SysDictClass(lEnum.current()).makeObject();
        if (fieldHandler.fieldHandled(_fieldName))
        {
            return fieldHandler;
        }
    }
    return null;
}
